1007	Status CollectionImpl::execute_compact_task(
1008	    std::vector<SegmentTask::Ptr> &tasks) const {
1009	  Status s;
1010	  for (auto &task : tasks) {
1011	    s = SegmentHelper::Execute(task);
1012	    if (!s.ok()) {
1013	      return s;
1014	    }
1015	  }
1016	
1017	  return Status::OK();
1018	}
