1517	Status CollectionImpl::switch_to_new_segment_for_writing(
1518	    const CollectionSchema::Ptr &schema) {
1519	  auto s = writing_segment_->dump();
1520	  CHECK_RETURN_STATUS(s);
1521	
1522	  s = segment_manager_->add_segment(writing_segment_);
1523	  CHECK_RETURN_STATUS(s);
1524	
1525	  // when create new segment, segment meta should create a first new block
1526	  // meta
1527	  auto new_segment = Segment::CreateAndOpen(
1528	      path_, schema == nullptr ? *schema_ : *schema, allocate_segment_id(),
1529	      writing_segment_->meta()->max_doc_id() + 1, id_map_, delete_store_,
1530	      version_manager_,
1531	      SegmentOptions{false, options_.enable_mmap_, options_.max_buffer_size_});
1532	  if (!new_segment) {
1533	    return new_segment.error();
1534	  }
1535	
1536	  Version version = version_manager_->get_current_version();
1537	  auto writing_segment_meta = writing_segment_->meta();
1538	  writing_segment_meta->remove_writing_forward_block();
1539	  s = version.add_persisted_segment_meta(writing_segment_meta);
1540	  CHECK_RETURN_STATUS(s);
1541	
1542	  writing_segment_ = new_segment.value();
1543	  version.reset_writing_segment_meta(writing_segment_->meta());
1544	  version.set_next_segment_id(segment_id_allocator_.load());
1545	
1546	  s = version_manager_->apply(version);
1547	  CHECK_RETURN_STATUS(s);
1548	  s = version_manager_->flush();
1549	  CHECK_RETURN_STATUS(s);
1550	
1551	  return Status::OK();
1552	}
