35	 * @param name The collection name (default: "crash_recovery_test")
36	 * @return CollectionSchema::Ptr The test schema
37	 */
38	inline CollectionSchema::Ptr CreateTestSchema(
39	    const std::string &name = "crash_recovery_test") {
40	  auto schema = std::make_shared<CollectionSchema>(name);
41	  schema->set_max_doc_count_per_segment(10000);
42	
43	  schema->add_field(
44	      std::make_shared<FieldSchema>("int32_field", DataType::INT32, false));
45	  schema->add_field(
46	      std::make_shared<FieldSchema>("int64_field", DataType::INT64, true));
47	  schema->add_field(
48	      std::make_shared<FieldSchema>("float_field", DataType::FLOAT, true));
49	  schema->add_field(
50	      std::make_shared<FieldSchema>("string_field", DataType::STRING, false));
51	  schema->add_field(
52	      std::make_shared<FieldSchema>("bool_field", DataType::BOOL, false));
53	  schema->add_field(std::make_shared<FieldSchema>("array_int32_field",
54	                                                  DataType::ARRAY_INT32, true));
55	  schema->add_field(std::make_shared<FieldSchema>(
56	      "array_string_field", DataType::ARRAY_STRING, false));
57	  schema->add_field(std::make_shared<FieldSchema>(
58	      "dense_fp32_field", DataType::VECTOR_FP32, 128, false,
59	      std::make_shared<HnswIndexParams>(MetricType::L2)));
60	  schema->add_field(std::make_shared<FieldSchema>(
61	      "sparse_fp32_field", DataType::SPARSE_VECTOR_FP32, 0, false,
62	      std::make_shared<HnswIndexParams>(MetricType::IP)));
63	
64	  return schema;
65	}
66	
