68	/**
69	 * @brief Create a test document with deterministic values based on doc_id.
70	 *
71	 * Document pattern:
72	 * - pk: "pk_{doc_id}"
73	 * - int32_field: doc_id (cast to int32)
74	 * - int64_field: doc_id, null if doc_id % 60 == 0
75	 * - float_field: doc_id / 1000.0, null if doc_id % 70 == 0
76	 * - string_field: "{version}_{doc_id}"
77	 * - bool_field: doc_id % 2 == 0 or flipped if version % 2 !=0
78	 * - array_int32_field: [doc_id, doc_id+1, doc_id+2], null if doc_id % 100 == 0
79	 * - array_string_field: ["str_{version}_0", ...]
80	 * - dense_fp32_field: vector where dense[i] = (doc_id + i) / 1000.0f
81	 * - sparse_fp32_field: sparse vector with indices [0, 10, ...]
82	 *
83	 * @param doc_id The document ID (determines all field values)
84	 * @param version The version of the document
85	 * @return Doc The created document
86	 */
87	inline Doc CreateTestDoc(uint64_t doc_id, int version) {
88	  Doc doc;
89	
90	  // Set primary key
91	  std::string pk = "pk_" + std::to_string(doc_id);
92	  doc.set_pk(pk);
93	
94	  // Set scalar fields
95	  doc.set<int32_t>("int32_field", static_cast<int32_t>(doc_id));
96	
97	  // int64_field: nullable, null if doc_id % 60 == 0
98	  if (doc_id % 60 != 0) {
99	    doc.set<int64_t>("int64_field", static_cast<int64_t>(doc_id));
100	  }
101	
102	  // float_field: nullable, null if doc_id % 70 == 0
103	  if (doc_id % 70 != 0) {
104	    doc.set<float>("float_field", static_cast<float>(doc_id) / 1000.0f);
105	  }
106	
107	  // string_field: "value_{id}" or "updated_value_{id}"
108	  std::string string_value =
109	      std::to_string(version) + "_" + std::to_string(doc_id);
110	  doc.set<std::string>("string_field", string_value);
111	
112	  // bool_field: alternating based on doc_id, flipped if updated
113	  bool bool_value = (doc_id % 2 == 0);
114	  if (version % 2 != 0) {
115	    bool_value = !bool_value;
116	  }
117	  doc.set<bool>("bool_field", bool_value);
118	
119	  // array_int32_field: nullable, null if doc_id % 100 == 0
120	  if (doc_id % 100 != 0) {
121	    std::vector<int32_t> array_int32;
122	    for (int i = 0; i < 3; i++) {
123	      array_int32.push_back(static_cast<int32_t>(doc_id + i));
124	    }
125	    doc.set<std::vector<int32_t>>("array_int32_field", array_int32);
126	  }
127	
128	  // array_string_field: ["str_0", "str_1", ...] or ["updated_str_0", ...]
129	  std::vector<std::string> array_string;
130	  size_t array_size = doc_id % 5 + 1;  // 1 to 5 elements
131	  for (size_t i = 0; i < array_size; i++) {
132	    array_string.push_back("str_" + std::to_string(version) + "_" +
133	                           std::to_string(i));
134	  }
135	  doc.set<std::vector<std::string>>("array_string_field", array_string);
136	
137	  // dense_fp32_field: deterministic pattern
138	  std::vector<float> dense(128);
139	  for (int i = 0; i < 128; i++) {
140	    dense[i] = static_cast<float>(doc_id + i) / 1000.0f;
141	  }
142	  doc.set<std::vector<float>>("dense_fp32_field", dense);
143	
144	  // sparse_fp32_field: sparse vector with indices [0, 10, 20, ..., 100]
145	  // Values based on doc_id: value = (doc_id + index) / 1000.0
146	  std::vector<uint32_t> sparse_indices;
147	  std::vector<float> sparse_values;
148	  for (uint32_t idx = 0; idx <= 100; idx += 10) {
149	    sparse_indices.push_back(idx);
150	    sparse_values.push_back(static_cast<float>(doc_id + idx) / 1000.0f);
151	  }
152	  doc.set<std::pair<std::vector<uint32_t>, std::vector<float>>>(
153	      "sparse_fp32_field", std::make_pair(sparse_indices, sparse_values));
154	
155	  return doc;
156	}
