160	/**
161	 * @brief Locate a binary by name, searching common paths and TEST_BINARY_DIR.
162	 *
163	 * @param binary_name The base name of the binary (e.g. "data_generator")
164	 * @return std::string The canonical path to the found binary
165	 * @throws std::runtime_error if the binary is not found
166	 */
167	inline std::string LocateBinary(const std::string &binary_name) {
168	  namespace fs = std::filesystem;
169	  std::cout << "Current path: " << fs::current_path() << std::endl;
170	
171	  std::vector<std::string> candidates;
172	  const std::vector<std::string> search_paths = {"./", "./bin/"};
173	
174	  for (const auto &p : search_paths) {
175	    candidates.push_back(p);
176	  }
177	#ifdef _WIN32
178	  for (const auto &p : search_paths) {
179	    candidates.push_back(p + "Debug/");
180	    candidates.push_back(p + "Release/");
181	  }
182	#endif
183	
184	  const char *test_binary_dir = std::getenv("TEST_BINARY_DIR");
185	  if (test_binary_dir != nullptr) {
186	    candidates.push_back(std::string(test_binary_dir) + "/");
187	    candidates.push_back(std::string(test_binary_dir) + "/bin/");
188	  }
189	
190	  for (auto &p : candidates) {
191	    p += binary_name;
192	#ifdef _WIN32
193	    p += ".exe";
194	#endif
195	  }
196	
197	  for (const auto &p : candidates) {
198	    if (fs::exists(p)) {
199	      return fs::canonical(p).string();
200	    }
201	  }
202	  throw std::runtime_error(binary_name + " binary not found");
203	}
